 */
public object FfiConverterTypeTusherNode: FfiConverter<TusherNode, Pointer> {

    override fun lower(value: TusherNode): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): TusherNode {
        return TusherNode(value)
    }

    override fun read(buf: ByteBuffer): TusherNode {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: TusherNode) = 8UL

    override fun write(value: TusherNode, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



