sealed class TusherFfiException: kotlin.Exception() {
    
    class InitializationException(
        
        val `msg`: kotlin.String
        ) : TusherFfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class NetworkException(
        
        val `msg`: kotlin.String
        ) : TusherFfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class SyncException(
        
        val `msg`: kotlin.String
        ) : TusherFfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class TransferException(
        
        val `msg`: kotlin.String
        ) : TusherFfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class StorageException(
        
        val `msg`: kotlin.String
        ) : TusherFfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class PeerNotFound(
        
        val `peerId`: kotlin.String
        ) : TusherFfiException() {
        override val message
            get() = "peerId=${ `peerId` }"
    }
    
    class InvalidArgument(
        
        val `msg`: kotlin.String
        ) : TusherFfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class InternalException(
        
        val `msg`: kotlin.String
        ) : TusherFfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<TusherFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): TusherFfiException = FfiConverterTypeTusherFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeTusherFfiError : FfiConverterRustBuffer<TusherFfiException> {
    override fun read(buf: ByteBuffer): TusherFfiException {
        

        return when(buf.getInt()) {
            1 -> TusherFfiException.InitializationException(
                FfiConverterString.read(buf),
                )
            2 -> TusherFfiException.NetworkException(
                FfiConverterString.read(buf),
                )
            3 -> TusherFfiException.SyncException(
                FfiConverterString.read(buf),
                )
            4 -> TusherFfiException.TransferException(
                FfiConverterString.read(buf),
                )
            5 -> TusherFfiException.StorageException(
                FfiConverterString.read(buf),
                )
            6 -> TusherFfiException.PeerNotFound(
                FfiConverterString.read(buf),
                )
            7 -> TusherFfiException.InvalidArgument(
                FfiConverterString.read(buf),
                )
            8 -> TusherFfiException.InternalException(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TusherFfiException): ULong {
        return when(value) {
            is TusherFfiException.InitializationException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is TusherFfiException.NetworkException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is TusherFfiException.SyncException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is TusherFfiException.TransferException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is TusherFfiException.StorageException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is TusherFfiException.PeerNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`peerId`)
            )
            is TusherFfiException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is TusherFfiException.InternalException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: TusherFfiException, buf: ByteBuffer) {
        when(value) {
            is TusherFfiException.InitializationException -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is TusherFfiException.NetworkException -> {
                buf.putInt(2)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is TusherFfiException.SyncException -> {
                buf.putInt(3)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is TusherFfiException.TransferException -> {
                buf.putInt(4)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is TusherFfiException.StorageException -> {
                buf.putInt(5)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is TusherFfiException.PeerNotFound -> {
                buf.putInt(6)
                FfiConverterString.write(value.`peerId`, buf)
                Unit
            }
            is TusherFfiException.InvalidArgument -> {
                buf.putInt(7)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is TusherFfiException.InternalException -> {
                buf.putInt(8)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





